% MATLAB Reference Script for Venturi Meter Cd Determination

% Student-entered apparatus parameters
d1 = 20.0; % Inlet pipe diameter (mm)
d2 = 15.0; % Throat diameter (mm)
tank_length = 0.4; % Tank length (m)
tank_width = 0.4;  % Tank width (m)
rise = 10.0;       % Water level rise (cm)
g = 9.81;          % Gravity (m/s^2)

% Derived apparatus dimensions
d1_m = d1 / 1000;
d2_m = d2 / 1000;
a1 = (pi / 4) * d1_m^2; % 3.1416e-4 m^2
a2 = (pi / 4) * d2_m^2; % 1.7671e-4 m^2
tank_area = tank_length * tank_width; % 0.16 m^2
vol = tank_area * (rise / 100);     % 0.016 m^3

% Observed trial data
h1 = [18.5, 17.0, 16.0, 15.0, 14.0]; % cm
h2 = [7.0,  8.0,  9.0,  10.0, 11.0]; % cm
t  = [24.0, 27.0, 30.0, 35.0, 45.0]; % s

% Dynamic calculations
del_h = abs(h1 - h2);
h_m = del_h / 100; % Convert cm to m
H = h_m .* 12.6;
Qact = vol ./ t;
Qth = (a1 * a2 .* sqrt(2 * g .* H)) ./ sqrt(a1^2 - a2^2);
Cd = Qact ./ Qth;

% Linear regression fit
p = polyfit(Qth, Cd, 1);
Q_fit = linspace(min(Qth), max(Qth), 100);
Cd_fit = polyval(p, Q_fit);

% Plotting with MATLAB default aesthetic
figure;
plot(Qth, Cd, 'o-', 'Color', [0 0.447 0.741], 'LineWidth', 1.5, 'DisplayName', 'Observed Data');
hold on;
plot(Q_fit, Cd_fit, '--', 'Color', [0.85 0.325 0.098], 'LineWidth', 1.5, 'DisplayName', 'Theoretical Line');
box on; grid on;
xlabel('Theoretical Flow Rate Qth (m^3/s)');
ylabel('Coefficient of Discharge (Cd)');
title('Venturi Meter Calibration (Cd vs Qth)');
ylim([0.50 0.70]);
legend('Location', 'northeast');
